const A2S_HEADER = Buffer.from([0xff, 0xff, 0xff, 0xff]);
const A2S_INFO_BODY = Buffer.concat([
  Buffer.from([0x54]),                            // 'T'
  Buffer.from("Source Engine Query\0", "ascii"),
]);

function cstring(buf: Buffer, at: number): { value: string; next: number } {
  const end = buf.indexOf(0, at);
  const stop = end === -1 ? buf.length : end;
  return { value: buf.subarray(at, stop).toString("utf8"), next: stop + 1 };
}

export function a2sInfo(host: string, port: number): Promise<LiveStatus | null> {
  const query = Buffer.concat([A2S_HEADER, A2S_INFO_BODY]);
  return udpQuery(host, port, [query], (msg, send) => {
    if (msg.length < 5) return null;

    /* Since 2020 most servers answer the first A2S_INFO with a challenge
       (`ff ff ff ff 41 <4 bytes>`) and only answer for real once the query is
       re-sent with those four bytes appended. That is the `ff ff ff ff 41` the
       port audits in lib/games.ts saw from our own servers. */
    if (msg[4] === 0x41) {
      send(Buffer.concat([query, msg.subarray(5, 9)]));
      return null;                                  // keep waiting for the real reply
    }
    if (msg[4] !== 0x49) return null;               // not S2A_INFO

    let at = 5;
    at += 1;                                        // protocol byte
    const name = cstring(msg, at); at = name.next;
    const map = cstring(msg, at); at = map.next;
    const folder = cstring(msg, at); at = folder.next;
    const game = cstring(msg, at); at = game.next;
    at += 2;                                        // Steam app id
    if (at + 1 >= msg.length) return null;
    const players = msg[at];
    const maxPlayers = msg[at + 1];

    return {
      online: players,
      // 255 is A2S's "unset" sentinel, not a real slot count.
      max: maxPlayers === 255 ? null : maxPlayers,
      motd: name.value.trim() || null,
      map: map.value.trim() || null,
    };
  });
}

