export async function queryLive(family: string, address: string): Promise<LiveStatus | null> {
  const protocol = QUERY_PROTOCOL[family as GameFamily];
  if (!protocol) return null;

  const cut = address.lastIndexOf(":");
  const hasPort = cut > 0 && /^\d+$/.test(address.slice(cut + 1));
  const host = hasPort ? address.slice(0, cut) : address;
  const port = hasPort ? Number(address.slice(cut + 1)) : joinPortFor(family as GameFamily).port;
  if (!host || !port) return null;

  try {
    if (protocol === "mc-java") return await mcJavaPing(host, port);
    if (protocol === "bedrock") return await bedrockPing(host, port);
    return await a2sInfo(host, port);
  } catch {
    return null;
  }
}

