/**
 * Steam / Valve A2S server query — A2S_INFO and A2S_PLAYER — as pure,
 * individually testable parsers plus a bounded UDP client.
 *
 * Spec: https://developer.valvesoftware.com/wiki/Server_queries
 *
 * Wire shapes handled here (all little-endian, header `ff ff ff ff`):
 *   request  A2S_INFO    0x54 "Source Engine Query\0" [challenge:4]
 *   reply    S2C_CHALLENGE 0x41 <challenge:4>   (since Dec 2020 usual for INFO,
 *                                                always for PLAYER)
 *   reply    S2A_INFO    0x49 proto name map folder game appid:u16 players max
 *                        bots type env visibility vac version [EDF…]
 *   request  A2S_PLAYER  0x55 <challenge:4>     (first send 0xffffffff)
 *   reply    S2A_PLAYER  0x44 count { index:u8 name\0 score:i32 duration:f32 }*
 *
 * Multi-packet replies (header `ff ff ff fe`) are NOT reassembled: a Valheim
 * INFO/PLAYER answer is far below the MTU and anything fragmented is treated as
 * "no answer" rather than guessed at.
 *
 * Honesty contract: every function resolves to `null` when the server did not
 * give a well-formed answer inside the timeout. Callers must render "no live
 * data", never a zero.
 */
import dgram from "node:dgram";

export const A2S_HEADER = Buffer.from([0xff, 0xff, 0xff, 0xff]);
const INFO_REQ = Buffer.concat([A2S_HEADER, Buffer.from([0x54]), Buffer.from("Source Engine Query\0", "ascii")]);
const NO_CHALLENGE = Buffer.from([0xff, 0xff, 0xff, 0xff]);

export type A2sInfo = {
  protocol: number;
  name: string;
  map: string;
  folder: string;
  game: string;
  appId: number;
  players: number;
  /** null when the server reports the 255 "unset" sentinel or 0. */
  maxPlayers: number | null;
  bots: number;
  /** "d" dedicated, "l" listen, "p" SourceTV relay. */
  serverType: string;
  /** "l" linux, "w" windows, "m"/"o" mac. */
  environment: string;
  passwordProtected: boolean;
  vac: boolean;
  version: string;
  /** EDF keywords string (Valheim puts its game version etc. here), when present. */
  keywords: string | null;
};

export type A2sPlayer = { index: number; name: string; score: number; durationSec: number };

function cstr(buf: Buffer, at: number): { value: string; next: number } | null {
  if (at >= buf.length) return null;
  const end = buf.indexOf(0, at);
  if (end === -1) return null; // unterminated string = malformed
  return { value: buf.subarray(at, end).toString("utf8"), next: end + 1 };
}

/** True for a well-formed single-packet A2S datagram of the given type byte. */
export function isA2sType(msg: Buffer, type: number): boolean {
  return msg.length >= 5 && msg.subarray(0, 4).equals(A2S_HEADER) && msg[4] === type;
}

/** Challenge number bytes out of an S2C_CHALLENGE (0x41) reply, or null. */
export function parseChallenge(msg: Buffer): Buffer | null {
  if (!isA2sType(msg, 0x41) || msg.length < 9) return null;
  return Buffer.from(msg.subarray(5, 9));
}

/** Parse an S2A_INFO (0x49) datagram. Returns null for anything malformed/truncated. */
export function parseInfo(msg: Buffer): A2sInfo | null {
  if (!isA2sType(msg, 0x49)) return null;
  let at = 5;
  if (at >= msg.length) return null;
  const protocol = msg[at++];
  const name = cstr(msg, at); if (!name) return null; at = name.next;
  const map = cstr(msg, at); if (!map) return null; at = map.next;
  const folder = cstr(msg, at); if (!folder) return null; at = folder.next;
  const game = cstr(msg, at); if (!game) return null; at = game.next;
  // appid(2) players max bots type env visibility vac = 2 + 7 bytes
  if (at + 9 > msg.length) return null;
  const appId = msg.readUInt16LE(at); at += 2;
  const players = msg[at++];
  const max = msg[at++];
  const bots = msg[at++];
  const serverType = String.fromCharCode(msg[at++]);
  const environment = String.fromCharCode(msg[at++]);
  const visibility = msg[at++];
  const vac = msg[at++] === 1;
  const version = cstr(msg, at); if (!version) return null; at = version.next;

  let keywords: string | null = null;
  if (at < msg.length) {
    const edf = msg[at++];
    try {
      if (edf & 0x80) at += 2;  // game port
      if (edf & 0x10) at += 8;  // SteamID
      if (edf & 0x40) {         // SourceTV port + name
        at += 2;
        const tv = cstr(msg, at); if (!tv) throw new Error("tv");
        at = tv.next;
      }
      if (edf & 0x20) {         // keywords
        const kw = cstr(msg, at);
        if (kw) { keywords = kw.value; at = kw.next; }
      }
    } catch { /* EDF is optional extra data — a bad tail must not void the real fields */ }
  }
  return {
    protocol, name: name.value, map: map.value, folder: folder.value, game: game.value, appId,
    players, maxPlayers: max === 255 || max === 0 ? null : max, bots,
    serverType, environment, passwordProtected: visibility === 1, vac, version: version.value, keywords,
  };
}

/** Parse an S2A_PLAYER (0x44) datagram. Returns null if malformed. */
export function parsePlayers(msg: Buffer): A2sPlayer[] | null {
  if (!isA2sType(msg, 0x44) || msg.length < 6) return null;
  const count = msg[5];
  let at = 6;
