  for (let i = 0; i < count; i++) {
    if (at >= msg.length) return null;
    const index = msg[at++];
    const name = cstr(msg, at); if (!name) return null; at = name.next;
    if (at + 8 > msg.length) return null;
    const score = msg.readInt32LE(at); at += 4;
    const durationSec = msg.readFloatLE(at); at += 4;
    out.push({ index, name: name.value, score, durationSec });
  }
  return out;
}

/* ── bounded UDP client ───────────────────────────────────────────────── */

/**
 * Send `first`, answer one challenge (by re-sending via `withChallenge`), and
 * resolve with the first datagram whose type byte is `want`. Always closes the
 * socket; resolves null on timeout/error/unexpected data.
 */
function exchange(
  host: string, port: number, first: Buffer, want: number,
  withChallenge: (c: Buffer) => Buffer, timeoutMs: number,
): Promise<Buffer | null> {
  return new Promise((resolve) => {
    const sock = dgram.createSocket("udp4");
    let done = false;
    let challenged = false;
    const finish = (v: Buffer | null) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      try { sock.close(); } catch { /* already closed */ }
      resolve(v);
    };
    const timer = setTimeout(() => finish(null), timeoutMs);
    timer.unref?.();
    const send = (b: Buffer) => sock.send(b, port, host, (e) => { if (e) finish(null); });
    sock.on("error", () => finish(null));
    sock.on("message", (msg) => {
      if (isA2sType(msg, want)) return finish(msg);
      const ch = parseChallenge(msg);
      if (ch && !challenged) { challenged = true; send(withChallenge(ch)); return; }
      // anything else (fragmented, wrong type, repeated challenge) = give up
      finish(null);
    });
    send(first);
  });
}

export function queryInfo(host: string, port: number, timeoutMs = 1500): Promise<A2sInfo | null> {
  return exchange(host, port, INFO_REQ, 0x49, (c) => Buffer.concat([INFO_REQ, c]), timeoutMs)
    .then((b) => (b ? parseInfo(b) : null)).catch(() => null);
}

