"use server";

/**
 * ADMIN-only actions for Nxeon community (free public shared) servers.
 * Every export re-checks requireArea("fleet") itself, validates every field
 * server-side, writes an AuditLog row, and is idempotent (upsert by slug).
 * No shell/SSH/Proxmox is touched here: the VM is provisioned out-of-band
 * (scripts/provision-public-valheim.sh) — this only records what exists.
 */
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireArea } from "./rbac";
import { recordAudit } from "./audit";
import { GAME_FAMILIES } from "./games";
import {
  PUBLIC_STATUSES, PASSWORD_POLICIES, validHost, validPort, probeNow, type LiveState,
} from "./free-public-server";

type Result = { ok: true } | { ok: false; error: string };

const clean = (s: unknown, max: number) => {
  const t = String(s ?? "").replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, "").trim();
  return t ? t.slice(0, max) : null;
};

const Schema = z.object({
  slug: z.string().regex(/^[a-z0-9][a-z0-9-]{1,30}$/, "Slug: lowercase letters, digits, dashes."),
  game: z.enum(GAME_FAMILIES),
  name: z.string().min(2).max(80),
  status: z.enum(PUBLIC_STATUSES),
  host: z.string().refine(validHost, "Host must be a DNS name (not an IP)."),
  port: z.coerce.number().refine(validPort, "Game port must be 1024-65534."),
  queryPort: z.coerce.number().refine(validPort, "Query port must be 1024-65534."),
  maxPlayers: z.coerce.number().int().min(1).max(200),
  passwordPolicy: z.enum(PASSWORD_POLICIES),
  region: z.string().regex(/^[a-z]{3}\d$/, "Region code like bhs1.").nullable(),
});

/** Create or update the row for `slug` from the admin form. */
export async function adminSaveFreePublicServer(formData: FormData): Promise<Result> {
  const admin = await requireArea("fleet");
  const raw = {
    slug: String(formData.get("slug") ?? "").trim().toLowerCase(),
    game: String(formData.get("game") ?? ""),
    name: clean(formData.get("name"), 80) ?? "",
    status: String(formData.get("status") ?? "PLANNED"),
    host: String(formData.get("host") ?? "").trim().toLowerCase(),
    port: formData.get("port"),
    queryPort: formData.get("queryPort"),
    maxPlayers: formData.get("maxPlayers"),
    passwordPolicy: String(formData.get("passwordPolicy") ?? "PUBLISHED"),
    region: clean(formData.get("region"), 8),
  };
  const p = Schema.safeParse(raw);
  if (!p.success) return { ok: false, error: p.error.issues[0]?.message ?? "Invalid input." };
  const d = p.data;
  const password = clean(formData.get("passwordHint"), 40);
  if (password && !/^[A-Za-z0-9_-]{5,40}$/.test(password)) {
    return { ok: false, error: "Published password: 5-40 letters/digits/dash/underscore (Valheim needs 5+ and not part of the world name)." };
  }
  if (d.passwordPolicy === "PUBLISHED" && !password && d.status === "LIVE") {
    return { ok: false, error: "A LIVE server with a published-password policy needs the current password." };
  }
  const data = {
    game: d.game, name: d.name, status: d.status, host: d.host, port: d.port, queryPort: d.queryPort,
    maxPlayers: d.maxPlayers, passwordPolicy: d.passwordPolicy, region: d.region,
    tagline: clean(formData.get("tagline"), 140),
    passwordHint: d.passwordPolicy === "PUBLISHED" ? password : null,
    rotation: clean(formData.get("rotation"), 60),
    wipePolicy: clean(formData.get("wipePolicy"), 300),
    notes: clean(formData.get("notes"), 2000),
  };
  const prev = await db.freePublicServer.findUnique({ where: { slug: d.slug }, select: { status: true } });
  await db.freePublicServer.upsert({ where: { slug: d.slug }, create: { slug: d.slug, ...data }, update: data });
  // Never log the password itself.
  await recordAudit(admin.id, "free_public_server.save", `slug=${d.slug} status=${prev?.status ?? "new"}->${d.status} host=${d.host}:${d.port}`);
  revalidatePath("/admin/free-servers");
  return { ok: true };
}

/** One-click status flip (LIVE / MAINTENANCE / RETIRED / PLANNED). */
export async function adminSetFreePublicStatus(id: string, status: string): Promise<Result> {
  const admin = await requireArea("fleet");
  if (!(PUBLIC_STATUSES as readonly string[]).includes(status)) return { ok: false, error: "Bad status." };
  const row = await db.freePublicServer.findUnique({ where: { id } });
  if (!row) return { ok: false, error: "Not found." };
  if (status === "LIVE" && row.passwordPolicy === "PUBLISHED" && !row.passwordHint) {
    return { ok: false, error: "Set the current published password before going LIVE." };
  }
  if (row.status === status) return { ok: true };
  await db.freePublicServer.update({ where: { id }, data: { status } });
  await recordAudit(admin.id, "free_public_server.status", `slug=${row.slug} ${row.status}->${status}`);
  revalidatePath("/admin/free-servers");
  return { ok: true };
}

/** Record a new published password after the on-box rotation (never logged). */
export async function adminSetFreePublicPassword(id: string, password: string): Promise<Result> {
  const admin = await requireArea("fleet");
  if (!/^[A-Za-z0-9_-]{5,40}$/.test(password)) return { ok: false, error: "5-40 letters/digits/dash/underscore." };
  const row = await db.freePublicServer.findUnique({ where: { id }, select: { slug: true, passwordPolicy: true } });
  if (!row) return { ok: false, error: "Not found." };
  if (row.passwordPolicy !== "PUBLISHED") return { ok: false, error: "This server's policy is OPEN." };
  await db.freePublicServer.update({ where: { id }, data: { passwordHint: password } });
  await recordAudit(admin.id, "free_public_server.password", `slug=${row.slug} rotated`);
  revalidatePath("/admin/free-servers");
  return { ok: true };
}

export type ProbeResult =
  | { ok: true; live: LiveState; playerListCount: number | null }
  | { ok: false; error: string };

/** On-demand health probe (a real A2S query to the public address). */
export async function adminProbeFreePublicServer(id: string): Promise<ProbeResult> {
  await requireArea("fleet");
  const row = await db.freePublicServer.findUnique({ where: { id }, select: { id: true, host: true, queryPort: true } });
  if (!row) return { ok: false, error: "Not found." };
  const r = await probeNow(row);
  return { ok: true, ...r };
}
