_VOID = {"area","base","br","col","embed","hr","img","input","link","meta","source","track","wbr"}
def balanced(html):
    """Stray end tags (no matching open element) — each one would close the
    page wrapper when the markup is injected, so a page with any fails."""
    class P(HTMLParser):
        def __init__(self): super().__init__(convert_charrefs=True); self.st = []; self.stray = []
