            if t not in _VOID: self.st.append(t)
        def handle_startendtag(self, t, a): pass
        def handle_endtag(self, t):
            if t in _VOID: return
            if t in self.st:
                while self.st and self.st.pop() != t: pass
            else:
                self.stray.append((t, self.getpos()))
    p = P(); p.feed(html); p.close()
    return p.stray

