 * request time.
 *
 * Prices are USD (the charge currency), formatted the way the design shows
 * them ("$12.78").
 */

/**
 * Money for display, in the VISITOR's currency — the live site's own rules
 * (lib/currency-display resolveDisplayCurrency: nx_currency cookie → geo →
 * operator default → USD; lib/currency convertAndFormat). Charges stay USD;
 * this is display only, exactly like the live marketing pages. USD keeps the
 * design's "$12.99" look. The currency is resolved once per request by
 * initDisplayFx() (called from nxmParams / the homepage) before any loader
 * formats a price. JSON-LD offers stay USD (they use raw numbers, not this).
 */
const fxBox = cache(() => ({ code: "USD", rate: 1, ready: false }));
export async function initDisplayFx() {
  const b = fxBox();
  if (!b.ready) {
    try { const d = await resolveDisplayCurrency(); b.code = d.currency; b.rate = d.rate; } catch { /* USD */ }
    b.ready = true;
  }
  return { code: b.code, rate: b.rate };
