  "/game-servers/directory": {"title": "Public Minecraft Servers", "description": "Browse community Minecraft servers hosted on Nxeon. Find survival, creative, SkyBlock and modded servers to join instantly — copy the address and connect.", "crumb": "Server directory"}, // live (its title carried a stray "| Nxeon" before the site suffix)
