import Link from "next/link";
import { listVisibleFreePublicServers, liveState, connectAddress } from "@/lib/free-public-server";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { deployHref } from "@/lib/deploy-intent";
import { CopyChip } from "@/components/customer/CopyChip";

/**
 * "Play free on Nxeon's community server" — shown on the customer Game servers
 * page only while an admin has a community server LIVE (otherwise renders
 * nothing, so it is inert until the VM exists). Live count is a real A2S query
 * with a short budget; when it can't answer we say so instead of showing 0.
 */
export async function CommunityServerCard() {
  const rows = await listVisibleFreePublicServers();
  if (!rows.length) return null;
  const cards = await Promise.all(rows.map(async (r) => ({ r, live: await liveState(r, 1200) })));
  return (
    <div className="grid gap-3 sm:grid-cols-2">
      {cards.map(({ r, live }) => {
        const meta = GAME_DISPLAY[r.game as GameFamily] ?? { name: r.game, glyph: "🎮" };
        const status =
          r.status === "MAINTENANCE" ? "Under maintenance"
          : live.state === "online" ? `${live.players}${live.max ?? r.maxPlayers ? ` / ${live.max ?? r.maxPlayers}` : ""} playing now`
          : live.state === "unreachable" ? "Not answering right now"
          : "Checking status…";
        return (
          <div key={r.id} className="card relative overflow-hidden">
            <div className="flex items-start justify-between gap-2">
              <div className="flex min-w-0 items-center gap-3">
                <span className="text-2xl leading-none" aria-hidden>{meta.glyph}</span>
                <div className="min-w-0">
                  <p className="truncate font-medium text-slate-100">{r.name}</p>
                  <p className="mt-0.5 text-xs text-slate-500">{status} · up to {r.maxPlayers} players</p>
                </div>
              </div>
              <span className="rounded-full border border-cyan-400/40 bg-cyan-400/10 px-2 py-0.5 text-[9px] font-bold uppercase tracking-wide text-cyan-300">Nxeon community</span>
            </div>
            {r.tagline && <p className="mt-3 text-xs text-slate-400">{r.tagline}</p>}
            <div className="mt-3 flex flex-wrap gap-2">
              <CopyChip label="Address" value={connectAddress(r)} />
              {r.passwordPolicy === "PUBLISHED" && r.passwordHint && <CopyChip label="Password" value={r.passwordHint} />}
            </div>
            <div className="mt-3 flex flex-wrap gap-4 text-xs font-medium">
              <Link href={`/free-${r.game}-server`} className="text-brand-300 hover:text-white">How to join →</Link>
              <Link href={deployHref({ service: "game", gameFamily: r.game })} className="text-brand-300 hover:text-white">Get your own private {meta.name} server →</Link>
            </div>
          </div>
        );
      })}
    </div>
  );
}
