  const cfgGames = Object.fromEntries(games.map((g) => {
    const ts = tiers.get(g.family)!;
    const slots = ts.map((t) => t.slots).filter((s): s is number => s != null);
    return [g.family, { n: g.name, g: g.genres[0] ?? "Game server", img: art[g.family].cover, max: slots.length ? Math.max(...slots) : 32, url: g.route ? staged(g.route) : null,
      t: ts.map((t) => ({ ram: t.ram, slots: t.slots, p: t.p, i: t.i, href: t.href })) }];
  }));
  const ft = tiers.get(first.family)!;
  const players = Math.min(10, cfgGames[first.family].max);
  const rec = ft.find((t) => t.slots == null || t.slots >= players) ?? ft[ft.length - 1];
  const R0 = regions[0];
  const tile = (f: string) => `<div class="cg-w"><button type="button" class="cg" data-k="${f}" aria-pressed="${f === first.family}">${art[f].cover ? `<img src="${esc(art[f].cover!)}" alt="" width="360" height="520" loading="lazy">` : ""}<span>${esc(cfgGames[f].n)}</span></button>${cfgGames[f].url ? `<a class="cg-a" href="${esc(cfgGames[f].url!)}" aria-label="${esc(cfgGames[f].n)} server hosting">View page →</a>` : ""}</div>`;
  // a free Minecraft tier exists (lib/actions-free-minecraft.ts) — real
  // setting, silent when it's off (owner 2026-09-27: mention it here too)
  const [freeMcOn, freeMcRamMb] = await Promise.all([
    getSettingBool("free_minecraft_enabled", false), getSettingInt("free_minecraft_ram_mb", 1024),
  ]);
  const freeMcGb = Math.round((freeMcRamMb / 1024) * 10) / 10;
  const freemc = freeMcOn
    ? `<p class="gx-free"><b>Just want to try Minecraft first?</b> <a href="${staged("/free-minecraft")}">Get a free ${freeMcGb} GB server →</a></p>`
    : "";

  const addons = ipCents > 0
    ? `<label class="cfg-add"><input type="checkbox" id="a-ip"><span><b>Dedicated IPv4</b><small>Your own public IP</small></span><em>+${usd(ipCents)}</em></label>`
    : `<label class="cfg-add"><input type="checkbox" id="a-ip" checked disabled><span><b>Dedicated IPv4</b><small>Your own public IP</small></span><em>Included</em></label>`;

  // library
const regionLink = (c: Ctx, r: DeployRegion) =>
  `<a class="gl-reg" href="${esc(staged(`${c.route}/${r.slug}`))}">${r.cc ? `<span class="flag flag-${r.cc}"></span>` : ""}<div><b>${esc(c.name)} in ${esc(r.label)}</b><small>${esc(r.info?.blurb ?? r.city)}</small></div><span class="gl-go">→</span></a>`;

function moreHtml(c: Ctx) {
  const hub = staged("/game-servers");
  if (!c.region) {
    const big = c.freeMc
      ? `<a class="gl-free" href="${esc(staged("/free-minecraft"))}"><span class="au-chip"><i class="d"></i>Free forever tier</span><h2>Not ready to pay? Try it free.</h2><p>A free ${esc(c.name)} server with no card and no queue. Upgrade in one click when your friends show up.</p><span class="gl-go">Get a free server →</span></a>`
      : `<a class="gl-free" href="${esc(hub)}"><span class="au-chip"><i class="d"></i>${c.games.length} games</span><h2>Playing more than one game?</h2><p>Every game on Nxeon runs from the same account and panel, from ${money(Math.min(...c.games.map((g) => g.fromCents)) / 100)} a month.</p><span class="gl-go">See every game →</span></a>`;
    return `<section class="section" id="more" style="padding-top:0"><div class="container gloc">${big}${c.regions.map((r) => regionLink(c, r)).join("")}</div></section>`;
  }
  const others = c.regions.filter((r) => r.code !== c.region!.code).map((r) => regionLink(c, r)).join("");
  const all = `<a class="gl-reg" href="${esc(staged(c.route))}"><span class="gl-ic">${I("game")}</span><div><b>All ${esc(c.name)} hosting</b><small>Every region${c.variants.length ? ", server type" : ""} and plan</small></div><span class="gl-go">→</span></a>`;
  const last = c.freeMc
    ? `<a class="gl-reg" href="${esc(staged("/free-minecraft"))}"><span class="gl-ic">${I("spark")}</span><div><b>Try ${esc(c.name)} free</b><small>No card, no queue</small></div><span class="gl-go">→</span></a>`
    : `<a class="gl-reg" href="${esc(hub)}"><span class="gl-ic">${I("spark")}</span><div><b>Every game</b><small>${c.games.length} games, one account</small></div><span class="gl-go">→</span></a>`;
  return `<section class="section" id="more" style="padding-top:0"><div class="container glinks">${all}${others}${last}</div></section>`;
}

function faqItems(c: Ctx) {
  const where = c.region ? ` in ${c.region.city}` : "";
    "custom.lede": `When you outgrow ${c.topT.ram} GB, or need a whole network of ${c.name} servers, we’ll design a setup around your players${c.withMods ? ", your mods" : ""} and your growth.`,
    "loaders:html": loadersHtml(c), "mods:html": modsHtml(c), "more:html": moreHtml(c), "faq:html": faqHtml(c),
    "flow.pick": `${cap(list(pickBits))}, all on one page.`,
    "flow.boot": `We install ${c.name}${cmods ? " and your mods" : ""}${r ? ` in ${r.label}` : ""}.`,
    "final.h": `Your ${c.world} is waiting${r ? ` in ${r.label}` : ""}.`,
    "final.alt:html": c.freeMc
      ? `<a class="nxm-glassbtn" href="${esc(staged("/free-minecraft"))}"><span class="nxm-bt">Try free first</span></a>`
      : `<a class="nxm-glassbtn" href="${esc(staged("/game-servers"))}"><span class="nxm-bt">See every game</span></a>`,
