p='/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/fv-shots.mjs'; s=open(p).read()
s=s.replace("""await Promise.all([page.waitForNavigation({ timeout: 120000 }).catch(() => {}), page.click('button[type="submit"]')]);""","""await Promise.all([page.waitForURL(u => !u.pathname.startsWith('/login'), { timeout: 90000 }).catch(() => {}), page.press('input[name="password"]', 'Enter')]);""")
s=s.replace("""  await shot(o, `fv-page-${n}`, "/nxm/free-valheim-server");
  await shot(o, `directory-${n}`, "/nxm/game-servers/directory");
  await shot(o, `hub-${n}`, "/nxm/game-servers");
""","""  if (n === "m") { await shot(o, `fv-page-${n}`, "/nxm/free-valheim-server");
  await shot(o, `directory-${n}`, "/nxm/game-servers/directory"); } else await shot(o, `directory-${n}`, "/nxm/game-servers/directory");
""")
open(p,'w').write(s)
EOF
rm -f $S/fv-run.done; nohup $S/heavy.sh bash $S/fv-run.sh > $S/fv-run.out 2>&1 &
cd /opt/nxeon-wt-freevalheim && git add tools/nxm/native/free-valheim-server app/nxm/_pages/free-valheim-server && printf 'Free Valheim page: drop the console wording that contradicted the FAQ\n\nCo-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>\n' > $S/fv-c3.txt && git commit -q -F $S/fv-c3.txt && echo ok

